{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Encainide, a methoxybenzamide with a basic azacycle, had absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20% for the query's similar methoxyaryl/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Letermovir, a lipophilic heteroaromatic drug with methoxy and basic piperazine motifs, had absolute oral bioavailability of 93.8% in healthy participants, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Daridorexant, containing a methoxyphenyl amide and heterocyclic amine, had absolute oral bioavailability of 62% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alizapride, a methoxybenzamide with a pyrrolidine side chain, had absolute oral availability of 72.5%, directly supporting high F for the query's methoxyaryl-pyrrolidine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Brexpiprazole, a lipophilic basic drug with piperazine and aryl ether features, had absolute oral bioavailability of 95%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Vernakalant, a methoxyphenyl ether with a pyrrolidine, had absolute oral bioavailability of 58 ± 19% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "The active metabolite of nabumetone, a methoxynaphthalene ketone, had oral bioavailability of 38%, still above the 20% threshold and supportive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Teriflunomide, a methoxybenzamide, had oral bioavailability of 100%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide was described as having low bioavailability in many patients, indicating that first-pass/metabolic variability can reduce F below 20% in a subset; this is contradictory but outweighed by the majority of high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show mean absolute oral bioavailability ≥30%, mostly 58–100%, with only encainide showing subset variability; the query's lipophilic trimethoxyphenyl ketone with a basic pyrrolidine is consistent with high F, so predict high (F ≥ 20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "First-pass metabolism and transporter effects for the exact trimethoxyphenyl ketone/pyrrolidine scaffold are unknown; encainide data show metabolic polymorphism can lower F in a subset."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

